const e="diabetic-ketoacidosis",t="Диабетический кетоацидоз / Гипергликемические состояния",a="#10b981",i=[{id:"glucose",label:"Глюкоза крови",layer:"raw",type:"lab",unit:"ммоль/л",normal:"3.9-6.1",value:28,group:"metabolism",description:"Глюкоза >13.9 ммоль/л — критерий ДКА. >33.3 — гиперосмолярное состояние."},{id:"ph",label:"pH крови",layer:"raw",type:"lab",unit:"",normal:"7.35-7.45",value:7.12,group:"gasometry",description:"pH <7.30 — критерий ДКА. <7.10 — тяжёлый. <7.00 — критический, высокая смертность."},{id:"hco3",label:"Бикарбонаты (HCO₃)",layer:"raw",type:"lab",unit:"ммоль/л",normal:"22-26",value:10,group:"gasometry",description:"HCO₃⁻ <18 ммоль/л — критерий ДКА. <10 — тяжёлый. <5 — крайне тяжёлый."},{id:"ketones",label:"Кетоновые тела (β-OH-бутират)",layer:"raw",type:"lab",unit:"ммоль/л",normal:"<0.6",value:4.8,group:"metabolism",description:"Кетоны в крови/моче — ацетоацетат, β-оксимасляная кислота. >3 ммоль/л — ДКА."},{id:"anion_gap",label:"Анионный промежуток",layer:"raw",type:"lab",unit:"ммоль/л",normal:"8-16",value:24,group:"metabolism",description:"Анионный разрыв >12 — метаболический ацидоз. >20 — ДКА. >30 — тяжёлый."},{id:"potassium",label:"Калий",layer:"raw",type:"lab",unit:"ммоль/л",normal:"3.5-5.0",value:5.8,group:"electrolyte",description:"Калий — псевдогипокалиемия при ДКА (внутриклеточный сдвиг). Общий дефицит 3–5 ммоль/кг."},{id:"sodium",label:"Натрий",layer:"raw",type:"lab",unit:"ммоль/л",normal:"136-145",value:132,group:"electrolyte",description:"Натрий — псевдогипонатриемия из-за гипергликемии. Коррекция: +1.6 ммоль/л на каждые 5.6 ммоль/л глюкозы >5.6."},{id:"osmolality",label:"Осмолярность плазмы",layer:"raw",type:"lab",unit:"мосмоль/кг",normal:"275-295",value:320,group:"metabolism",description:"Осмолярность >320 мОсм/кг — гиперосмолярное состояние. >340 — тяжёлое."},{id:"creatinine",label:"Креатинин",layer:"raw",type:"lab",unit:"мкмоль/л",normal:"62-115",value:140,group:"kidney",description:"Креатинин — ОПН при гиповолемии, шоке. Ацетоацетат может фальсифицировать (креатинин-ассаи)."},{id:"wbc",label:"Лейкоциты",layer:"raw",type:"lab",unit:"×10⁹/л",normal:"4-9",value:15,group:"cbc",description:"Лейкоциты — лейкоцитоз при ДКА без инфекции (стрессовый ответ). >15 — подозрение на инфекцию."},{id:"lactate",label:"Лактат",layer:"raw",type:"lab",unit:"ммоль/л",normal:"0.5-1.6",value:2.2,group:"metabolism",description:"Лактат >2.0 — гипоперфузия при шоке. >4.0 — тяжёлый шок, плохой прогноз."},{id:"polyuria",label:"Полиурия",layer:"findings",type:"symptom",description:"Полиурия — осмотический диурез при гипергликемии. >3 л/сут. Приводит к дегидратации."},{id:"polydipsia",label:"Полидапсия (неутолимая жажда)",layer:"findings",type:"symptom",description:"Полидипсия — компенсаторная жажда при осмотическом диурезе."},{id:"kussmaul",label:"Дыхание Куссмауля",layer:"findings",type:"sign",description:"Дыхание Куссмауля — глубокое, шумное, учащённое. Компенсация метаболического ацидоза."},{id:"acetone_odor",label:"Запах ацетона",layer:"findings",type:"sign",description:"Запах ацетона — изо рта, мочи. Ацетоацетат и ацетон в выдыхаемом воздухе."},{id:"abdominal_pain",label:"Боль в животе",layer:"findings",type:"symptom",description:'Боль в животе — псевдоперитонит при ДКА. Может имитировать "острый живот".'},{id:"dehydration",label:"Обезвоживание",layer:"findings",type:"sign",severity:"II-III степени",description:"Дегидратация — сухие слизистые, снижение тургора, тахикардия, ортостатическая гипотензия."},{id:"altered_consciousness",label:"Нарушение сознания",layer:"findings",type:"sign",severity:"сомноленция → кома",description:"Нарушение сознания — гиперосмолярность, ацидоз, гипоксемия. От спутанности до комы."},{id:"nausea_vomiting",label:"Тошнота/рвота",layer:"findings",type:"symptom",description:"Тошнота и рвота — кетоацидоз, гастропарез. Усугубляет дегидратацию."},{id:"weight_loss",label:"Потеря веса",layer:"findings",type:"symptom",description:"Потеря веса — оsmотический диурез, катаболизм. Типична при новом диабете."},{id:"dka",label:"Диабетический кетоацидоз (ДКА)",layer:"hypotheses",type:"diagnosis",prevalence:"30% СД1",ptp:"high",description:"ДКА — диабетический кетоацидоз. Абсолютный дефицит инсулина. Гипергликемия, кетонемия, ацидоз. Тип 1 СД."},{id:"hhs",label:"Гиперосмолярное гипергликемическое состояние (ГОГС)",layer:"hypotheses",type:"diagnosis",prevalence:"1% СД2",ptp:"medium",description:"ГНК — гиперосмолярное некетотическое состояние. Тип 2 СД. Глюкоза >33, осмолярность >320, без ацидоза."},{id:"hypoglycemia",label:"Гипогликемия",layer:"hypotheses",type:"diagnosis",prevalence:"10%",ptp:"medium",description:"Гипогликемия — глюкоза <3.3. Нейрогликопения, потливость, тахикардия, судороги, кома."},{id:"lactic_acidosis",label:"Молочнокислый ацидоз",layer:"hypotheses",type:"diagnosis",prevalence:"2%",ptp:"low",description:"Молочно-кислый ацидоз — тип A (гипоперфузия) или B (метформин, сепсис). Лактат >5, pH <7.35."},{id:"renal_acidosis",label:"Почечный тубулярный ацидоз",layer:"hypotheses",type:"diagnosis",prevalence:"редко",ptp:"low",description:"Почечный ацидоз — неспособность почек экскретировать H⁺ или реабсорбировать HCO₃⁻. Гиперкалиемия."},{id:"alcoholic_ketoacidosis",label:"Алкогольный кетоацидоз",layer:"hypotheses",type:"diagnosis",prevalence:"1%",ptp:"low",description:"Алкогольный кетоацидоз — голодание + алкоголь. Кетоны↑, pH норма/низкий. Глюкоза норма/низкая."},{id:"diff_dka_vs_hhs",label:"ДКА vs ГОГС",layer:"differential",type:"comparison"},{id:"diff_ketoacidosis",label:"Диффдиагностика кетоацидозов",layer:"differential",type:"algorithm"},{id:"guideline_ada_2023",label:"ADA Standards of Care: DKA/HHS 2023",layer:"evidence",type:"guideline",grade:"A",year:2023,description:"ADA Standards 2023 — управление ДКА и ГНК. Инсулин, инфузия, электролиты."},{id:"rct_insulin_dka",label:"RCT: инсулин 0.1 vs 0.05 Ед/кг/час при ДКА",layer:"evidence",type:"rct",grade:"A",year:2011,n:150,description:"RCT инсулина — непрерывная инфузия 0.1 Е/кг/ч стандарт при ДКА. Снижение глюкозы 50–70 мг/дл/ч."},{id:"meta_fluid_resuscitation",label:"Мета-анализ: объём инфузий при ДКА",layer:"evidence",type:"meta-analysis",grade:"A",year:2020,n:2e3,description:"Мета-анализ инфузии — физиологический раствор первый выбор. Избегать гипохлоремического ацидоза."},{id:"temp",label:"Температура",layer:"raw",type:"vital",unit:"°C",normal:"36.0-37.0",value:37.8,group:"vitals",description:"Температура — норма или субфебрильная при ДКА. Лихорадка >38°C — инфекционный триггер."},{id:"hr",label:"ЧСС",layer:"raw",type:"vital",unit:"уд/мин",normal:"60-100",value:110,group:"vitals",description:"ЧСС — тахикардия при гиповолемии, ацидозе, лихорадке."},{id:"rr",label:"ЧДД",layer:"raw",type:"vital",unit:"/мин",normal:"12-20",value:28,group:"vitals",description:"ЧДД — компенсаторная тахипноэ (Kussmaul). pH <7.2 — глубокое дыхание."},{id:"bp",label:"АД",layer:"raw",type:"vital",unit:"мм рт.ст.",normal:"120/80",value:"95/60",group:"vitals",description:"АД — гипотензия при гиповолемии, шоке. Требует инфузии, инсулина."},{id:"crp",label:"СРБ",layer:"raw",type:"lab",unit:"мг/л",normal:"<5",value:25,group:"inflammation",description:"СРБ — неспецифический маркер. Повышен при инфекционном триггере."},{id:"amylase",label:"Амилаза",layer:"raw",type:"lab",unit:"Ед/л",normal:"28-100",value:180,group:"pancreas",description:"Амилаза — лёгкое повышение при ДКА (слюнная железа). Не указывает на панкреатит."},{id:"lipase",label:"Липаза",layer:"raw",type:"lab",unit:"Ед/л",normal:"13-60",value:220,group:"pancreas",description:"Липаза — норма при ДКА. Повышена при панкреатите как триггере."},{id:"tachycardia",label:"Тахикардия",layer:"findings",type:"sign",description:"Тахикардия — гиповолемия, ацидоз, лихорадка. Компенсаторный ответ."},{id:"tachypnea",label:"Тахипноэ",layer:"findings",type:"sign",description:"Тахипноэ — дыхание Куссмауля. Компенсация ацидоза. RR >24."},{id:"fever",label:"Лихорадка",layer:"findings",type:"symptom",description:"Лихорадка — инфекционный триггер. При чистом ДКА обычно нормотермия."},{id:"confusion",label:"Спутанность сознания",layer:"findings",type:"sign",description:"Спутанность — гиперосмолярность, ацидоз. Ранняя стадия нарушения сознания."},{id:"fruity_breath",label:"Запах ацетона (фруктовый)",layer:"findings",type:"sign",description:"Фруктовый запах — ацетон в выдыхаемом воздухе. Характерен для ДКА."}],s=[{source:"glucose",target:"dka",type:"key_marker",weight:.95},{source:"glucose",target:"hhs",type:"key_marker",weight:.95},{source:"glucose",target:"hypoglycemia",type:"key_marker",weight:1},{source:"ph",target:"dka",type:"key_marker",weight:.95},{source:"ph",target:"lactic_acidosis",type:"supports",weight:.8},{source:"ph",target:"renal_acidosis",type:"supports",weight:.7},{source:"hco3",target:"dka",type:"key_marker",weight:.9},{source:"hco3",target:"renal_acidosis",type:"supports",weight:.75},{source:"ketones",target:"dka",type:"key_marker",weight:.98},{source:"ketones",target:"alcoholic_ketoacidosis",type:"key_marker",weight:.9},{source:"ketones",target:"hhs",type:"discriminates",weight:.85},{source:"anion_gap",target:"dka",type:"key_marker",weight:.9},{source:"anion_gap",target:"lactic_acidosis",type:"supports",weight:.8},{source:"anion_gap",target:"renal_acidosis",type:"discriminates",weight:.75},{source:"osmolality",target:"hhs",type:"key_marker",weight:.95},{source:"osmolality",target:"dka",type:"supports",weight:.7},{source:"lactate",target:"lactic_acidosis",type:"key_marker",weight:.95},{source:"lactate",target:"dka",type:"discriminates",weight:.7},{source:"potassium",target:"dka",type:"associated",weight:.75},{source:"creatinine",target:"dka",type:"associated",weight:.6},{source:"creatinine",target:"hhs",type:"associated",weight:.65},{source:"polyuria",target:"dka",type:"supports",weight:.8},{source:"polyuria",target:"hhs",type:"supports",weight:.8},{source:"polydipsia",target:"dka",type:"supports",weight:.75},{source:"polydipsia",target:"hhs",type:"supports",weight:.75},{source:"kussmaul",target:"dka",type:"supports",weight:.9},{source:"kussmaul",target:"lactic_acidosis",type:"supports",weight:.7},{source:"acetone_odor",target:"dka",type:"supports",weight:.95},{source:"acetone_odor",target:"alcoholic_ketoacidosis",type:"supports",weight:.85},{source:"abdominal_pain",target:"dka",type:"supports",weight:.7},{source:"dehydration",target:"dka",type:"supports",weight:.85},{source:"dehydration",target:"hhs",type:"supports",weight:.9},{source:"altered_consciousness",target:"hhs",type:"supports",weight:.9},{source:"altered_consciousness",target:"dka",type:"supports",weight:.75},{source:"altered_consciousness",target:"hypoglycemia",type:"supports",weight:.95},{source:"nausea_vomiting",target:"dka",type:"supports",weight:.7},{source:"weight_loss",target:"dka",type:"supports",weight:.6},{source:"dka",target:"diff_dka_vs_hhs",type:"compared_in",weight:1},{source:"hhs",target:"diff_dka_vs_hhs",type:"compared_in",weight:1},{source:"diff_ketoacidosis",target:"diff_dka_vs_hhs",type:"includes",weight:1},{source:"dka",target:"guideline_ada_2023",type:"covered_in",weight:1},{source:"hhs",target:"guideline_ada_2023",type:"covered_in",weight:1},{source:"dka",target:"rct_insulin_dka",type:"treated_in",weight:1},{source:"dka",target:"meta_fluid_resuscitation",type:"treated_in",weight:1},{source:"diff_dka_vs_hhs",target:"guideline_ada_2023",type:"described_in",weight:1},{source:"hr",target:"tachycardia",type:"generates",weight:1},{source:"rr",target:"tachypnea",type:"generates",weight:1},{source:"temp",target:"fever",type:"generates",weight:1},{source:"tachycardia",target:"dka",type:"supports",weight:.8},{source:"tachycardia",target:"hhs",type:"supports",weight:.75},{source:"tachypnea",target:"dka",type:"supports",weight:.9},{source:"tachypnea",target:"lactic_acidosis",type:"supports",weight:.7},{source:"fever",target:"dka",type:"associated",weight:.6},{source:"fever",target:"hhs",type:"associated",weight:.55},{source:"confusion",target:"dka",type:"supports",weight:.8},{source:"confusion",target:"hhs",type:"supports",weight:.85},{source:"confusion",target:"hypoglycemia",type:"supports",weight:.9},{source:"fruity_breath",target:"dka",type:"supports",weight:.95},{source:"fruity_breath",target:"alcoholic_ketoacidosis",type:"supports",weight:.85},{source:"crp",target:"dka",type:"associated",weight:.55},{source:"wbc",target:"dka",type:"associated",weight:.65},{source:"amylase",target:"dka",type:"supports",weight:.6},{source:"lipase",target:"dka",type:"supports",weight:.65},{source:"bp",target:"dka",type:"supports",weight:.7},{source:"bp",target:"hhs",type:"supports",weight:.75},{source:"sodium",target:"dka",type:"associated",weight:.6},{source:"guideline_ada_2023",target:"lactic_acidosis",type:"covered_in",weight:1},{source:"guideline_ada_2023",target:"alcoholic_ketoacidosis",type:"covered_in",weight:1}],r={dka:{description:"Диабетический кетоацидоз — острое осложнение сахарного диабета, характеризующееся триадой: гипергликемия, кетоз и метаболический ацидоз. Чаще при СД 1 типа.",criteria:["Глюкоза >13.9 ммоль/л","pH <7.30 или HCO₃ <18 ммоль/л","Кетонемия >3.0 ммоль/л или умеренная кетонурия","Анионный промежуток >10 ммоль/л"],prevalence:"30-40% пациентов с СД1 (хотя бы раз)",complications:["Церебральный отёк (особенно у детей)","Гипокалиемия","Острая почечная недостаточность","Тромбоэмболические осложнения","Рабдомиолиз","Шок"],treatment:["Инфузия 0.9% NaCl 1-1.5 л в первый час","Инсулин в/в 0.1 Ед/кг/час (болюс 0.1 Ед/кг при тяжёлом ДКА)","Коррекция калия: при K⁺ <3.3 — калий ДО инсулина; при 3.3-5.3 — калий с инсулином; при >5.3 — без калия","Бикарбонат при pH <6.9 (100 ммоль в 400 мл 0.9% NaCl)","Переход на подкожный инсулин при pH >7.3, HCO₃ >18, возможность приёма пищи"],followup:"Обучение пациента, пересмотр схемы инсулинотерапии, выявление триггера"},hhs:{description:"Гиперосмолярное гипергликемическое состояние — тяжёлое осложнение СД 2 типа с экстремальной гипергликемией, гиперосмолярностью и отсутствием значимого кетоза.",criteria:["Глюкоза >33.3 ммоль/л","pH >7.30","HCO₃ >18 ммоль/л","Осмолярность >320 мосмоль/кг","Кетонемия <3.0 ммоль/л или отсутствие кетонурии"],prevalence:"1% пациентов с СД2",complications:["Тромбоэмболические осложнения (высокий риск)","Церебральный отёк","Острая почечная недостаточность","Синдром распада опухоли"],treatment:["Инфузия 0.9% NaCl (переход на 0.45% при гипернатриемии)","Инсулин в/в 0.05-0.1 Ед/кг/час (без болюса)","Коррекция калия аналогично ДКА","Профилактика тромбозов (НМГ)","Медленное снижение осмолярности (≤3 мосмоль/кг/час)"],followup:"Пожизненная антикоагуляция при ТЭЛА, контроль гликемии"}},o={diff_dka_vs_hhs:{headers:["Признак","ДКА","ГОГС"],rows:[{feature:"Тип диабета",dka:"Чаще СД 1",hhs:"Чаще СД 2"},{feature:"Глюкоза",dka:">13.9 ммоль/л",hhs:">33.3 ммоль/л"},{feature:"pH",dka:"<7.30",hhs:">7.30 (обычно >7.45)"},{feature:"HCO₃",dka:"<18 ммоль/л",hhs:">18 ммоль/л"},{feature:"Кетонемия",dka:">3.0 ммоль/л",hhs:"<3.0 ммоль/л"},{feature:"Осмолярность",dka:"<320 мосмоль/кг",hhs:">320 мосмоль/кг"},{feature:"Анионный промежуток",dka:">10 ммоль/л",hhs:"<12 ммоль/л"},{feature:"Начало",dka:"Часы-1-2 дня",hhs:"Дни-недели"},{feature:"Сознание",dka:"Ясное до сомноленции",hhs:"Сомноленция → кома"},{feature:"Запах ацетона",dka:"Ярко выражен",hhs:"Отсутствует"},{feature:"Смертность",dka:"<5%",hhs:"10-20%"}]}},p={guideline_ada_2023:{title:"Standards of Care in Diabetes—2023: Hyperglycemic Crises in Adults",authors:"Dhatariya KK et al.",journal:"Diabetes Care",year:2023,design:"Clinical guideline",grade:"A",key_findings:["Инсулин в/в 0.1 Ед/кг/час — стандарт ДКА","Бикарбонат только при pH <6.9","ГОГС: инсулин без болюса, медленная коррекция осмолярности"],quality:"Высокое (GRADE: A)"},rct_insulin_dka:{title:"Low-dose vs standard-dose insulin in diabetic ketoacidosis",authors:"Kitabchi AE et al.",journal:"Diabetes Care",year:2011,n:150,design:"RCT",grade:"A",key_findings:["0.1 Ед/кг/час = 0.05 Ед/кг/час по скорости снижения глюкозы","0.1 Ед/кг/час быстрее снижает кетоны","Рекомендована доза 0.1 Ед/кг/час"],quality:"Высокое (GRADE: A)"},meta_fluid_resuscitation:{title:"Fluid resuscitation in diabetic ketoacidosis: systematic review and meta-analysis",authors:"Fayfman M et al.",journal:"Diabetes Obes Metab",year:2020,n:2e3,design:"Meta-analysis of 12 RCTs",grade:"A",key_findings:["0.9% NaCl — стандарт первого выбора","Балансированные растворы снижают риск гиперхлоремического ацидоза","Скорость 1-1.5 л/час первый час при гиповолемии"],quality:"Высокое (GRADE: A)"}},l={dka:[{time:0,event:"Начало",glucose:28,ph:7.12,hco3:10,symptom:"Полиурия, жажда"},{time:2,event:"2 часа",glucose:28,ph:7.1,hco3:9,symptom:"Тошнота, боль в животе"},{time:4,event:"4 часа",glucose:28,ph:7.08,hco3:8,symptom:"Дыхание Куссмауля"},{time:6,event:"Госпитализация",glucose:30,ph:7.05,hco3:7,symptom:"Сомноленция"},{time:7,event:"1 час терапии",glucose:25,ph:7.08,hco3:8,symptom:"Инсулин + NaCl"},{time:9,event:"3 часа терапии",glucose:18,ph:7.18,hco3:12,symptom:"Улучшение"},{time:12,event:"6 часов терапии",glucose:12,ph:7.28,hco3:16,symptom:"Ясное сознание"},{time:18,event:"12 часов",glucose:9,ph:7.35,hco3:20,symptom:"Стабилизация"},{time:24,event:"24 часа",glucose:8,ph:7.38,hco3:22,symptom:"Переход на п/к инсулин"}]},d={id:e,label:t,color:a,nodes:i,links:s,details:r,comparisons:o,evidence:p,timelines:l};export{a as color,o as comparisons,d as default,r as details,p as evidence,e as id,t as label,s as links,i as nodes,l as timelines};
